+    ruleset.patterns.len()
+}
+
+/// Derive a stable suffix from a test-case input for the generated test id.
+fn sanitize(s: &str) -> String {
+    s.chars()
+        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
+        .take(24)
+        .collect()
